    int maxRun = -1;
    int runCount = 0;
    int numCount = 0;
    bool insideParen = false;
    int alphaRun = 0;

    for (int i = 0; i < len; i++) {
        char ch = str[i];

        auto isAlpha = [](char c) {
            return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
        };

        if (!insideParen) {
            if (isAlpha(ch)) {
                runCount++;
